examples.setup:
var open by remember { mutableStateOf(true) }
var invitees by remember { mutableStateOf(listOf<String>()) }
var inviteRole by remember { mutableStateOf<String?>("viewer") }
var access by remember { mutableStateOf<String?>("invited") }
var roleOf by remember { mutableStateOf(mapOf("alex@example.com" to "editor", "sam@example.com" to "commenter")) }
val roles = listOf(
    MonarchRoleOption("viewer", "Viewer"),
    MonarchRoleOption("commenter", "Commenter"),
    MonarchRoleOption("editor", "Editor"),
)
val people = listOf(
    MonarchEntityPickerEntity("u4", "Jordan Kim", description = "jordan@example.com"),
    MonarchEntityPickerEntity("u5", "Riley Chen", description = "riley@example.com"),
    MonarchEntityPickerEntity("u6", "Taylor Brooks", description = "taylor@example.com"),
)

var open by remember { mutableStateOf(false) }
var invitees by remember { mutableStateOf(listOf<String>()) }
val people = listOf(MonarchEntityPickerEntity("kat", "Katherine Johnson", description = "kat@example.com"))

examples.code:
MonarchButton(text = "Share", onClick = { open = true })
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Share “Q3 plan”") {
        val sheet = this
        // The sheet scrolls as one column: no lazy list inside it.
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchEntityPicker(label = "Invite people", entities = people, selected = invitees, onSelectedChange = { invitees = it })
            MonarchMemberRow(name = "You", email = "you@example.com", role = "owner", self = true)
            MonarchCopyField(value = "https://example.com/d/q3-plan", label = "Link")
            MonarchButton(
                text = "Done",
                onClick = { sheet.dismiss() },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
            )
        }
    }
}
